#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-09-04
/**
 * fh-ready-check.mjs: the FH-ready handler policy gate.
 *
 * Handlers under src/ (excluding lib/, entries/, types.ts, tests) must not
 * import node:fs or node:child_process, and must not call fetch directly.
 * Side effects go through HookContext or an injected deps object, so the same
 * handler runs today behind run-hook.mjs and, if Claude Code ships Function
 * Hooks (anthropics/claude-code#91870), behind a $-backed context unchanged.
 *
 * Ratchet: every file in fh-ready-baseline.json is grandfathered. The gate
 * fails on a NEW offender, and on a baseline entry that no longer offends
 * (delete it from the baseline; the list only shrinks). Same shape as
 * validate-registry.mjs and known-dead-hooks.json.
 */
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const HOOKS_ROOT = join(__dirname, '..');
const SRC = join(HOOKS_ROOT, 'src');
const BASELINE_PATH = join(__dirname, 'fh-ready-baseline.json');

const IMPORT_RE = /from\s+['"]node:(?:fs|child_process)(?:\/promises)?['"]/;
const FETCH_RE = /\bfetch\(/;

function walk(dir, out = []) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    const st = statSync(p);
    if (st.isDirectory()) {
      if (name === 'node_modules' || name === '__tests__' || name === 'lib' || name === 'entries') continue;
      walk(p, out);
    } else if (name.endsWith('.ts') && !name.endsWith('.test.ts') && !name.endsWith('.d.ts') && name !== 'types.ts') {
      out.push(p);
    }
  }
  return out;
}

const baseline = new Set(JSON.parse(readFileSync(BASELINE_PATH, 'utf8')).files);
const offenders = new Set();
for (const file of walk(SRC)) {
  const rel = relative(HOOKS_ROOT, file);
  const text = readFileSync(file, 'utf8');
  if (IMPORT_RE.test(text) || FETCH_RE.test(text)) offenders.add(rel);
}

const fresh = [...offenders].filter((f) => !baseline.has(f)).sort();
const stale = [...baseline].filter((f) => !offenders.has(f)).sort();

if (fresh.length === 0 && stale.length === 0) {
  console.log(`fh-ready-check: OK (${offenders.size} grandfathered, 0 new)`);
  process.exit(0);
}
if (fresh.length) {
  console.error(`fh-ready-check: ${fresh.length} NEW handler(s) own their I/O (node:fs, node:child_process, or fetch). Take it through HookContext or an injected deps object instead:`);
  for (const f of fresh) console.error(`  ${f}`);
}
if (stale.length) {
  console.error(`fh-ready-check: ${stale.length} baseline entr${stale.length === 1 ? 'y' : 'ies'} no longer offend. Remove from fh-ready-baseline.json (the ratchet only shrinks):`);
  for (const f of stale) console.error(`  ${f}`);
}
process.exit(1);
